from collections import Counter

def countTriplets(nums1, nums2):
    def get_triplets(arr1, arr2):
        count1 = Counter(arr1)
        count2 = Counter(arr2)
        total = 0

        # Pre-calculate unique values in arr2 to speed up loop
        unique_nums2 = list(count2.keys())

        for x, freq1 in count1.items():
            target = x * x
            for y in unique_nums2:
                if target % y == 0:
                    z = target // y
                    if z in count2:
                        if y < z:
                            total += freq1 * count2[y] * count2[z]
                        elif y == z:
                            total += freq1 * count2[y] * (count2[y] - 1) // 2
        return total

    return get_triplets(nums1, nums2) + get_triplets(nums2, nums1)

